// Instruction-level stop control. Values come exclusively from the stopped CPU.
export class PicoDebugger{
 constructor(runtime,info){this.runtime=runtime;this.info=info?.version===1?info:null;if(this.info){const {lines,variables}=this.info,end=0x10000000+runtime.image.length;if(!Array.isArray(lines)||lines.length>50000||!Array.isArray(variables)||variables.length>10000||lines.some(l=>!l||typeof l.file!=='string'||l.file.length>200||!Number.isInteger(l.line)||l.line<1||!Number.isInteger(l.address)||!Number.isInteger(l.to)||l.address<0x10000000||l.to>end||l.to<=l.address)||variables.some(v=>!v||typeof v.name!=='string'||v.name.length>200||!v.type||![undefined,'number'].includes(typeof v.type.size)||v.location!==undefined&&(!Array.isArray(v.location)||v.location.length>256)||v.frame!==undefined&&(!Array.isArray(v.frame)||v.frame.length>256)))throw Error('Pico debug bilgisi geçersiz; kodu yeniden derleyin.');}this.breakpoints=[];this.addresses=new Set();this.watches=[];this.reason=null;this.skip=null;}
 location(pc=this.runtime.core.PC){return this.info?.lines.find(l=>pc>=l.address&&pc<l.to)||null;}
 configure(points=[],watches=[]){if(points.length>256||watches.length>64)throw Error('Debugger sınırı aşıldı.');this.watches=watches.filter(n=>/^[A-Za-z_]\w*$/.test(n)).slice(0,64);this.addresses.clear();this.breakpoints=points.map(p=>{const rows=(this.info?.lines||[]).filter(l=>l.file===p.file&&l.stmt&&l.line>=p.line).sort((a,b)=>a.line-b.line||a.address-b.address),line=rows[0]?.line;const addresses=rows.filter(l=>l.line===line).map(l=>l.address);for(const a of addresses)this.addresses.add(a);return{file:p.file,line:p.line,resolvedLine:line??null,addresses};});}
 resume(){this.skip=this.reason?this.runtime.core.PC:null;this.reason=null;this.stepping=false;}
 shouldStop(){const pc=this.runtime.core.PC;if(this.skip===pc){this.skip=null;return false;}if(this.addresses.has(pc)){this.reason='breakpoint';return true;}return false;}
 beginStep(){this.origin=this.location();this.originSP=this.runtime.registers()[13];this.resume();this.stepping=true;this.stepCount=0;}
 afterInstruction(){if(!this.stepping)return false;this.stepCount++;const l=this.location();if(l&&(!this.origin||l.file!==this.origin.file||l.line!==this.origin.line||this.runtime.registers()[13]!==this.originSP)){this.reason='line';this.stepping=false;return true;}if(this.stepCount>=500000){this.reason='step-limit';this.stepping=false;return true;}return false;}
 memory(address,size){const r=this.runtime,a=address>>>0;if(!Number.isInteger(size)||size<1||size>8||!(a>=0x20000000&&a+size<=0x20000000+r.board.ram||a>=0x10000000&&a+size<=0x10000000+r.image.length))throw Error('Güvenli RAM/Flash dışında.');const bytes=new Uint8Array(size);for(let i=0;i<size;i++)bytes[i]=r.rp.readUint8(a+i);return bytes;}
 expression(bytes,frame){if(!Array.isArray(bytes))throw Error('Konum bilgisi yok.');let p=0,stack=[],registerValue=false;const leb=signed=>{let n=0,shift=0,c;do{if(p>=bytes.length||shift>35)throw Error('Konum ifadesi geçersiz.');c=bytes[p++];n+=(c&127)*2**shift;shift+=7;}while(c&128);return signed&&(c&64)?n-2**shift:n;};while(p<bytes.length){const op=bytes[p++];if(op===3){stack.push(new DataView(Uint8Array.from(bytes.slice(p,p+4)).buffer).getUint32(0,true));p+=4;}else if(op>=0x50&&op<=0x6f){stack.push(this.runtime.registers()[op-0x50]);registerValue=true;}else if(op>=0x70&&op<=0x8f)stack.push((this.runtime.registers()[op-0x70]+leb(true))>>>0);else if(op===0x91){const base=this.expression(frame);stack.push((base.value+leb(true))>>>0);}else if(op===0x23)stack[stack.length-1]+=leb(false);else if(op===0x9f)registerValue=true;else throw Error('Desteklenmeyen DWARF konumu.');}if(stack.length!==1||!Number.isFinite(stack[0]))throw Error('Konum çözülemedi.');return{value:stack[0]>>>0,registerValue};}
 readVariable(v){try{const t=v.type;if(!t.encoding||![1,2,4,8].includes(t.size))throw Error('Bu tür henüz izlenemiyor.');const loc=this.expression(v.location,v.frame),b=loc.registerValue?new Uint8Array(new Uint32Array([loc.value]).buffer):this.memory(loc.value,t.size);if(b.length<t.size)throw Error('Yazmaç boyutu yetersiz.');const d=new DataView(b.buffer,b.byteOffset,b.byteLength);let value;if(t.encoding===4)value=t.size===4?d.getFloat32(0,true):d.getFloat64(0,true);else if(t.size===8)value=String([5,6].includes(t.encoding)?d.getBigInt64(0,true):d.getBigUint64(0,true));else{const signed=[5,6].includes(t.encoding);value=t.size===1?(signed?d.getInt8(0):d.getUint8(0)):t.size===2?(signed?d.getInt16(0,true):d.getUint16(0,true)):(signed?d.getInt32(0,true):d.getUint32(0,true));if(t.encoding===2)value=!!value;if(t.name==='pointer')value='0x'+(value>>>0).toString(16);}return{name:v.name,type:t.name,value,address:loc.registerValue?null:loc.value};}catch(e){return{name:v.name,type:v.type.name,unavailable:e.message};}}
 snapshot(paused){const pc=this.runtime.core.PC,vars=this.info?.variables||[],visible=vars.filter(v=>!v.scope||pc>=v.scope[0]&&pc<v.scope[1]).sort((a,b)=>(!!b.scope)-(!!a.scope)),unique=[...new Map(visible.map(v=>[v.name,v]).reverse()).values()];return{available:!!this.info,reason:this.reason,location:this.location(),breakpoints:this.breakpoints,variables:paused?unique.slice(0,100).map(v=>this.readVariable(v)):[],watches:paused?this.watches.map(name=>{const v=unique.find(v=>v.name===name);return v?this.readVariable(v):{name,unavailable:'Bu konumda görünür değil.'};}):[]};}
}
